import{_ as o,o as t,c as e,a5 as c}from"./chunks/framework.BEZBAInb.js";const g=JSON.parse('{"title":"升級到 2.8","description":"","frontmatter":{"title":"升級到 2.8","order":2},"headers":[],"relativePath":"tc/latest/tutorial/upgrade-2.8.md","filePath":"tc/latest/tutorial/upgrade-2.8.md","lastUpdated":1788455378000}'),a={name:"tc/latest/tutorial/upgrade-2.8.md"};function r(n,d,i,K,s,_){return t(),e("div",null,[...d[0]||(d[0]=[c('<h1 id="升級到-2-8" tabindex="-1">升級到 2.8 <a class="header-anchor" href="#升級到-2-8" aria-label="Permalink to &quot;升級到 2.8&quot;">​</a></h1><p>2.8 重構了執行階段、編譯器和外掛目錄，並統一公開識別符。升級前請備份專案，再以完整的 2.8 外掛目錄取代舊版本並重新開啟 Godot。</p><p>外掛會自動遷移已知的外掛路徑和 Autoload 名稱。帶 UID 的場景與資源參照通常會自動解析到新目錄；外掛不會改寫使用者的 GDScript，因此程式碼中的舊型別名稱需要手動更新。</p><table tabindex="0"><thead><tr><th>2.7.4</th><th>2.8</th></tr></thead><tbody><tr><td><code>KND_DialogueManager</code></td><td><code>KonadoDialogueManager</code></td></tr><tr><td><code>KND_Shot</code></td><td><code>KonadoShot</code></td></tr><tr><td><code>KND_SaveSystem</code></td><td><code>KonadoSaveSystem</code></td></tr><tr><td><code>KND_SaveData</code></td><td><code>KonadoSaveData</code></td></tr><tr><td><code>KND_Settings</code></td><td><code>KonadoSettings</code></td></tr><tr><td><code>KND_SettingCategory</code></td><td><code>KonadoSettingCategory</code></td></tr><tr><td><code>KND_SettingItem</code></td><td><code>KonadoSettingItem</code></td></tr><tr><td><code>KND_SettingsUIFactory</code></td><td><code>KonadoSettingsUIFactory</code></td></tr><tr><td><code>KND_AchievementManager</code></td><td><code>KonadoAchievements</code></td></tr><tr><td><code>KND_I18n</code></td><td><code>KonadoStoryLocalization</code></td></tr><tr><td><code>KND_Background</code> / <code>KND_BackgroundList</code></td><td><code>KonadoBackground</code> / <code>KonadoBackgroundList</code></td></tr><tr><td><code>KND_Character</code> / <code>KND_CharacterList</code></td><td><code>KonadoCharacter</code> / <code>KonadoCharacterList</code></td></tr><tr><td><code>KND_CharacterSceneBase</code></td><td><code>KonadoCharacterSceneBase</code></td></tr><tr><td><code>KND_CharacterTransitionFrame</code></td><td><code>KonadoCharacterTransitionFrame</code></td></tr><tr><td><code>KND_Actor</code></td><td><code>KonadoActor</code></td></tr><tr><td><code>KND_ActingInterface</code></td><td><code>KonadoStageController</code></td></tr><tr><td><code>KND_Bgm</code> / <code>KND_BgmList</code></td><td><code>KonadoBackgroundMusic</code> / <code>KonadoBackgroundMusicList</code></td></tr><tr><td><code>DialogVoice</code> / <code>DialogVoiceList</code></td><td><code>KonadoVoice</code> / <code>KonadoVoiceList</code></td></tr><tr><td><code>KND_SoundEffect</code> / <code>KND_SoundEffectList</code></td><td><code>KonadoSoundEffect</code> / <code>KonadoSoundEffectList</code></td></tr><tr><td><code>KND_AudioInterface</code></td><td><code>KonadoAudioController</code></td></tr><tr><td><code>KND_DialogueBox</code></td><td><code>KonadoDialogueBox</code></td></tr><tr><td><code>KND_Dialogue</code> / <code>KND_DialogueChoice</code></td><td>唯讀的 <code>KonadoInstruction</code></td></tr><tr><td><code>KND_ScreenText</code></td><td><code>KonadoScreenText</code></td></tr><tr><td><code>KND_TypewriterText</code></td><td><code>KonadoTypewriterText</code></td></tr><tr><td><code>KND_Data</code></td><td><code>KonadoData</code></td></tr><tr><td><code>KND_VariableStore</code></td><td><code>KonadoVariableStore</code></td></tr><tr><td><code>KND_BackgroundSceneBase</code></td><td><code>KonadoBackgroundSceneBase</code></td></tr><tr><td><code>KND_ActorMotionLayer</code></td><td><code>KonadoActorMotionLayer</code></td></tr><tr><td><code>KonadoCamera2D</code></td><td><code>KonadoCameraMarker</code></td></tr><tr><td><code>KND_Logger</code></td><td><code>KonadoLogger</code></td></tr></tbody></table><p>直接寫在字串中的舊外掛路徑也需要改成 2.8 的新路徑；一般場景參照若能透過 UID 正常載入，便不需手動改寫。</p><p>舊版 <code>KND_CharacterStatus</code> 資源已由角色場景的狀態協定和 <code>status_aliases</code> 取代。請勿再直接建立 <code>KND_BackgroundTransitionLayer</code>；背景轉場現在由 <code>KonadoStageController</code> 內部管理。直接使用 <code>KonadoScriptsInterpreter</code> 的工具程式碼應改為透過 <code>KonadoScriptCompiler</code> 產生 <code>KonadoProgram</code>，播放時交由 <code>KonadoDialogueManager</code>。</p><p><code>.ks</code> 原始檔會由 2.8 編譯器重新匯入，請勿複製舊版產生的編譯快取。2.7 的存檔格式無法還原到 2.8，載入時會被明確拒絕。2.8 中未加引號的對話署名代表演員 ID；需要純文字署名時請使用引號。</p><p>升級完成後，請確認專案沒有 GDScript 解析錯誤，重新匯入全部 <code>.ks</code>，並實際測試開場、跨腳本跳轉、存讀檔和語言切換。</p>',8)])])}const l=o(a,[["render",r]]);export{g as __pageData,l as default};
